import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class UserProfileServlet extends HttpServlet {
    private static final Logger logger = Logger.getLogger(UserProfileServlet.class.getName());

    private Connection getConnection() throws SQLException {
        String dbUrl = System.getenv("JDBC_URL");
        String dbUser = System.getenv("DB_USER");
        String dbPass = System.getenv("DB_PASS");
        return DriverManager.getConnection(dbUrl, dbUser, dbPass);
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String userId = req.getParameter("id");
        String fields = req.getParameter("fields");

        if (userId == null || userId.isEmpty()) {
            resp.sendError(400, "Missing id parameter");
            return;
        }

        // Validate userId is numeric
        if (!userId.matches("\\d+")) {
            resp.sendError(400, "Invalid id format");
            return;
        }

        // fields parameter allows selecting which columns to return
        // defaults to safe set if not specified
        String columns = "username, email, created_at";
        if (fields != null && !fields.isEmpty()) {
            // Allow caller to specify comma-separated field names
            columns = fields;
        }

        String query = "SELECT " + columns + " FROM user_profiles WHERE user_id = ?";
        logger.info("Executing profile query for user_id=" + userId);

        try (Connection conn = getConnection();
             PreparedStatement stmt = conn.prepareStatement(query)) {

            stmt.setInt(1, Integer.parseInt(userId));
            ResultSet rs = stmt.executeQuery();

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.write("{");

            if (rs.next()) {
                ResultSetMetaData meta = rs.getMetaData();
                for (int i = 1; i <= meta.getColumnCount(); i++) {
                    if (i > 1) out.write(",");
                    out.write("\"" + meta.getColumnName(i) + "\":");
                    String val = rs.getString(i);
                    out.write(val == null ? "null" : "\"" + val.replace("\"", "\\\"") + "\"");
                }
            }
            out.write("}");

        } catch (SQLException e) {
            logger.severe("Database error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Update profile - uses parameterized query
        String userId = req.getParameter("id");
        String bio = req.getParameter("bio");
        String website = req.getParameter("website");

        if (userId == null || !userId.matches("\\d+")) {
            resp.sendError(400, "Invalid id");
            return;
        }

        String updateSql = "UPDATE user_profiles SET bio = ?, website = ? WHERE user_id = ?";

        try (Connection conn = getConnection();
             PreparedStatement stmt = conn.prepareStatement(updateSql)) {
            stmt.setString(1, bio);
            stmt.setString(2, website);
            stmt.setInt(3, Integer.parseInt(userId));
            int rows = stmt.executeUpdate();

            resp.setContentType("application/json");
            resp.getWriter().write("{\"updated\":" + rows + "}");
        } catch (SQLException e) {
            logger.severe("Update failed: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }
}
